    const forbiddenAscii = /[^A-Za-z0-9 -]/;
    if (forbiddenAscii.test(normalized)) return false;
    const patternAscii = /^[A-Za-z0-9]+(?:[ -][A-Za-z0-9]+)*$/;
    return patternAscii.test(normalized);
