    if (specialCharCount > 2) {
        return false;
    }

    // Check for reasonable number of words (max 3 parts, e.g., "de la Cruz")
    const parts = trimmedName.split(/['\- ]+/).filter(part => part.length > 0);
    if (parts.length > 3) {
        return false;
    }

    // Each part must start with a letter
    for (const part of parts) {
