    const startsWithNumberPattern = /^\d+\s+[a-zA-ZÀ-ÿ]/.test(trimmedAddress);

    // 2. Texto seguido de número (ej: "Calle Principal 123")
    const endsWithNumberPattern = /[a-zA-ZÀ-ÿ].+\d+$/.test(trimmedAddress);

