    const words = trimmed.split(/[\s\-\/,]+/).filter(w => w.length > 1);
    const meaningfulWords = words.filter(w => /[a-zA-Z\u00C0-\u017F]{2,}/.test(w));
    if (meaningfulWords.length < 1) {
