    // Segmentos de letras/dígitos separados por un único espacio o un único guion
    ? /^(?=.{2,12}$)(?=.*[\p{L}\p{Nd}])[\p{L}\p{Nd}]+(?:[ -][\p{L}\p{Nd}]+)*$/u
    // Fallback ASCII: A-Z, a-z, 0-9
    : /^(?=.{2,12}$)(?=.*[A-Za-z0-9])[A-Za-z0-9]+(?:[ -][A-Za-z0-9]+)*$/;

