        /^[A-Z]{1,2}\d[A-Z\d]?\s?\d[A-Z]{2}$/i, // UK
        /^\d{7}$/                           // Brazil
    ];

    // Check against all patterns
    for (const pattern of patterns) {
        if (pattern.test(trimmed)) {
            return true;
        }
