    // Additional check for alphanumeric codes with dash/space
    const generalPattern = /^[A-Z0-9][A-Z0-9\s\-]{3,9}$/i;
    if (!generalPattern.test(trimmed)) {
        return false;
    }

    // Final validation: ensure it doesn't start/end with dash/space
    if (/^[\s\-]|[\s\-]$/.test(trimmed)) {
