  let parenDepth = 0;
  for (let i = 0; i < trimmed.length; i++) {
    if (trimmed[i] === '(') {
      parenDepth++;
      if (parenDepth > 1) return false;
    } else if (trimmed[i] === ')') {
      parenDepth--;
      if (parenDepth < 0) return false;
