  // - Letras con acentos y diacríticos de múltiples idiomas
  // - Guiones y apóstrofes (comunes en nombres)
  // - Puntos (para iniciales o abreviaciones)
  const patronNombre = /^[\p{L}\p{M}'\-\.\s]+$/u;

