    const caracteresPermitidos = /^[\p{L}\s'-]+$/u;

    if (!caracteresPermitidos.test(trimmed)) {
        return false;
    }

    // Validaciones específicas de estructura:

    // No puede empezar o terminar con espacios, guiones o apóstrofes
    if (/^[\s'-]|[\s'-]$/.test(trimmed)) {
        return false;
