    const palabrasNoCapitalizables = ['de', 'del', 'la', 'las', 'los', 'y', 'e', 'el', 'van', 'der', 'da', 'das', 'do', 'dos', 'von'];

    for (let i = 0; i < partes.length; i++) {
        const palabra = partes[i].toLowerCase();
        const primeraLetra = partes[i][0];

