    } else {
      const asc = cleanName.charCodeAt(i);
      if (32 <= asc && asc <= 96) { // ASCII de letras minúsculas
        minCuenta++;
      }
    }
  }

  // Si no se encontraron ni una letra, entonces devuelve falso porque no tiene palabras.
