    // (This is already covered by regex but being explicit)
    if (!/\p{L}/u.test(trimmed)) {
        return false;
    }

    // 5. Reject names that are only numbers or symbols
    if (/^\d+$/.test(trimmed.replace(/[\-'. ]/g, ''))) {
