    const letterCount = (trimmedAddress.match(/[a-zA-Z\u00C0-\u024F\u0400-\u04FF]/g) || []).length;
    const digitCount = (trimmedAddress.match(/\d/g) || []).length;
    const spaceCount = (trimmedAddress.match(/\s/g) || []).length;

