        // Check for valid characters: letters, hyphens, apostrophes, and periods
        const validPartRegex = /^[A-Za-zÀ-ÿ]+([-'.][A-Za-zÀ-ÿ]+)*$/;
        if (!validPartRegex.test(part)) {
