    const patterns = [
        // Estados Unidos: 5 dígitos o 5+4 dígitos (12345 o 12345-6789)
        /^\d{5}(-\d{4})?$/,

        // Canadá: A1A 1A1 (alterna letras y números, espacio opcional)
