    // Permitimos: letras, espacios, guiones, apóstrofes, puntos (para abreviaciones)
    // y caracteres diacríticos de múltiples idiomas
    const caracteresInvalidos = /[0-9_=+*&^%$#@!~`{}[\]\\|"<>?;:]/;
    if (caracteresInvalidos.test(nombreLimpio)) return false;

