  // punto (.), guiones (\p{Pd} y '-').
  const pattern = /^(?!.*(?:['\u02BC\u2019·.\-\p{Pd}\p{Zs}]{2,}))(?:\p{L}(?:[\p{L}\p{M}\p{Zs}'\u02BC\u2019·.\-\p{Pd}]*[\p{L}\p{M}])?)$/u;

