    /^\d{5}$/, // Germany, France, Austria, etc.
    /^\d{4}$/, // Norway, Denmark
    /^\d{3}\s?\d{2}$/, // Sweden
    /^\d{4}[A-Z]{2}$/i, // Netherlands
    /^\d{4}-\d{3}$/, // Portugal

    // Asia
