        /^[A-Za-zÀ-ÿĀ-žĄ-ž\u00C0-\u024F\u1E00-\u1EFF\u0400-\u04FF\-'’\s]+$/u,

        // Alfabeto árabe
        /^[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF\s]+$/u,

        // Alfabeto cirílico (ruso, ucraniano, etc.)
        /^[\u0400-\u04FF\u0500-\u052F\s]+$/u,

        // Alfabeto griego
        /^[\u0370-\u03FF\u1F00-\u1FFF\s]+$/u,

