  for (let i = 0; i < trimmedName.length; i++) {
    const code = trimmedName.charCodeAt(i);
    // Block control characters (except soft hyphen \u00AD and zero-width characters)
    if (code < 32 && code !== 9 && code !== 10 && code !== 13) {
