  //   periods (.), middle dot (·), and a range of hyphen/dash characters
  // The hyphen is placed at the end of the class to avoid range interpretation.
  const allowed = /^[\p{L}\p{M}\p{Zs}'’.\u00B7\u2010\u2011\u2012\u2013\u2014-]+$/u;
