    const start = name[0];
    const end = name[name.length - 1];

    let containsSpecialCharInFirstOrLastPosition = start.match(/[!,@#$%^&*()`~;:{}|<>\[\]?\-_]/) || end.match(/[!,@#$%^&*()`~;:{}|<>\[\]?\-_]/);

    if (containsSpecialCharInFirstOrLastPosition && containsSpecialCharInFirstOrLastPosition !== null) {
