    return false;
  }

  const trimmed = phoneNumber.trim();

  // Allow only valid phone characters: digits, spaces, hyphens, dots, parentheses, and leading '+'
  if (!/^\+?[0-9\s\-().]+$/.test(trimmed)) {
    return false;
