  // No permitir separadores dobles (espacio, guion, punto)
  if (/[ \-\.]{2,}/.test(s)) return false;

  // Extraer sólo dígitos y comprobar longitud razonable (entre 7 y 15 según E.164)
  const digits = s.replace(/\D/g, '');
