  if (normalized.length === 0) return false;

  // Now handle international prefixes: '+' or leading 00 or 011 (common international prefixes)
  let core = normalized;
  if (core[0] === '+') {
    core = core.slice(1);
  } else if (core.startsWith('00')) {
    core = core.slice(2);
  } else if (core.startsWith('011')) {
    core = core.slice(3);
