  // e.g., "90210", "SW1A 1AA", "K1A 0B1", "100-0001", "D-10115", "1012 JS"
  if (!/^[A-Za-z0-9]+([ -][A-Za-z0-9]+)*$/.test(normalized)) {
    return false;
