function isValidString(str) {
    if (str.length === 0) {
        return true;
    }
    var code = str.charCodeAt(0);
    if ((code >= 65 && code <= 90) || // Mayúsculas
        (code >= 97 && code <= 122)) {   // Minúsculas o Espacio
        return isValidString(str.substring(1));
    } else {
        return false;
    }
}

