    // Brunei (e.g., BT2328), Eswatini (e.g., H100)
    /^[A-Z]{2}\d{4}$/,
    /^[A-Z]\d{3}$/,

    // International country-code prefixes (e.g., LV-1050, FI-00100, SE-111 22)
    /^[A-Z]{1,2}[- ]\d{3,6}$/,
    /^[A-Z]{1,2}[- ]\d{3}[- ]\d{2}$/
  ];

