    if (!/^\d+$/.test(digits)) return false;
    return digits.length >= 7 && digits.length <= 15;
  }

  // Local numbers: digits only
  if (!/^\d+$/.test(cleaned)) return false;
  return cleaned.length >= 7 && cleaned.length <= 15;
}
