  // Contar dígitos en la parte principal (excluyendo la extensión)
  const mainPart = s.replace(/(?:\b|\s)(?:ext|ext\.|extension|x|#)\s*[\p{Nd}]+$/iu, '');
  const digitMatches = mainPart.match(/\p{Nd}/gu) || [];
