        let specialChars = /[^a-zA-Z\s!\"#¤%&/\(\)=§£€\[\]\*\+@\^\{\|\}<>\?~\_\-]*/g;

        // If a name contains any of these characters, it's not valid
        if (names[i].match(specialChars)) {
