    // Ireland / Eircode (e.g., "D02 X285")
    /^(?:[AC-FHKNPRTV-Y]\d{2}|D6W)\s*[0-9AC-FHKNPRTV-Y]{4}$/i,

    // Argentina (e.g., "C1024CWN")
    /^[A-Z]\d{4}[A-Z]{3}$/i,

