    // Verifica que la primera palabra (apellido) tengan entre 2 y 20 letras
    // Así mismo lo hace para los nombres 1 y opcionalmente el nombre 2
    for (let word of fullName.split(' ')) {

        if (!word.match(/^[a-zA-Z]{2,}$/)) {
            return false;
        }

    }

    return true;
