        for (let caracter of palabra) {
            if (!CharacterIsLetter(caracter)) {
                soloLetras = false;
                break;
            }
        }
        if (!soloLetras) return false;
    }

    // Sí se ha superado todas las comprobaciones, devuelve True
    return true;

function CharacterIsLetter(c) {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
